 static string EventFolder31(string host)=>Path.Combine(Store.Root,"Events",Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(host.ToUpperInvariant()))));
 void Event31(string host,string category,string signature,string text,string kind="Info",string details="",string at=""){
  var key=host.ToUpperInvariant()+"|"+category;if(eventSignatures31.GetValueOrDefault(key)==signature)return;eventSignatures31[key]=signature;
  var entry=new ClientEvent31{Kind=kind,Text=text,Details=details,At=DateTimeOffset.TryParse(at,out var observed)?observed.ToUniversalTime().ToString("o"):DateTime.UtcNow.ToString("o")};if(!recentEvents31.TryGetValue(host,out var list)){list=ReadEvents31(host,3);recentEvents31[host]=list;}list.Add(entry);list.Sort((a,b)=>string.CompareOrdinal(b.At,a.At));if(list.Count>3)list.RemoveRange(3,list.Count-3);
  try{var folder=EventFolder31(host);Directory.CreateDirectory(folder);File.AppendAllText(Path.Combine(folder,DateTime.Now.ToString("yyyy-MM-dd")+".jsonl"),JsonSerializer.Serialize(entry)+Environment.NewLine);var cutoff=DateTime.Now.AddDays(-Math.Clamp(Store.Read("event-days31.json",30),1,365));foreach(var file in Directory.GetFiles(folder,"*.jsonl"))if(DateTime.TryParseExact(Path.GetFileNameWithoutExtension(file),"yyyy-MM-dd",null,System.Globalization.DateTimeStyles.None,out var day)&&day<cutoff.Date)File.Delete(file);Store.Write("event-signatures31.json",eventSignatures31);}catch{ /* Recording must not change the result of the remote operation. */ }
 }
 static List<ClientEvent31> ReadEvents31(string host,int limit){var result=new List<ClientEvent31>();var folder=EventFolder31(host);try{if(!Directory.Exists(folder))return result;foreach(var file in Directory.GetFiles(folder,"*.jsonl").OrderByDescending(f=>Path.GetFileName(f))){foreach(var line in File.ReadLines(file).TakeLast(limit).Reverse()){try{var e=JsonSerializer.Deserialize<ClientEvent31>(line);if(e!=null)result.Add(e);}catch{}if(result.Count>=limit)return result;}if(result.Count>=limit)break;}}catch{}return result;}
 public static string ConnectionBrief31(string error){if(string.IsNullOrWhiteSpace(error))return "Причина не получена";if(AccessError(error))return "Отказано в доступе WinRM; проверьте права и учётную запись";if(error.Contains("отмен",StringComparison.OrdinalIgnoreCase)||error.Contains("canceled",StringComparison.OrdinalIgnoreCase)||error.Contains("вовремя",StringComparison.OrdinalIgnoreCase))return "Нет ответа за время проверки; выполнение задания этим не отменено";var text=error.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()??"Нет ответа";return text.Length>140?text[..140]+"…":text;}
