 void EventHistory_Click(object sender,RoutedEventArgs e){if(ComputerGrid.SelectedItem is not ComputerRow row)return;var window=new Window{Owner=this,Title="События · "+row.Name,Width=850,Height=550,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new DockPanel{Margin=new(14)};var top=new WrapPanel();DockPanel.SetDock(top,Dock.Top);panel.Children.Add(top);var filter=new CheckBox{Content="Только ошибки и предупреждения",Margin=new(4)};top.Children.Add(filter);var all=ReadEvents31(row.Host,500);var list=new ListBox{SelectionMode=SelectionMode.Extended,DisplayMemberPath="Display",ItemsSource=all};var style=new Style(typeof(ListBoxItem));style.Setters.Add(new Setter(Control.ForegroundProperty,new System.Windows.Data.Binding("Brush")));list.ItemContainerStyle=style;panel.Children.Add(list);void Show(){list.ItemsSource=filter.IsChecked==true?all.Where(x=>x.Kind is "Error" or "Warning").ToList():all;}filter.Checked+=(s,a)=>Show();filter.Unchecked+=(s,a)=>Show();var copy=new Button{Content="Копировать"};copy.Click+=(s,a)=>{var selected=list.SelectedItems.Cast<ClientEvent31>().ToList();Clipboard.SetText(string.Join(Environment.NewLine,(selected.Count>0?selected:((IEnumerable<ClientEvent31>)list.ItemsSource).ToList()).Select(x=>x.Display+(x.Details.Length>0?"\n"+x.Details:""))));};top.Children.Add(copy);var details=new Button{Content="Подробности"};details.Click+=(s,a)=>{if(list.SelectedItem is not ClientEvent31 selected)return;var text=new TextBox{Text=selected.Display+"\n\n"+selected.Details,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};new Window{Owner=window,Title="Подробности события",Width=720,Height=400,Content=text,WindowStartupLocation=WindowStartupLocation.CenterOwner}.ShowDialog();};top.Children.Add(details);var load=new Button{Content="Загрузить до 10 000 событий"};load.Click+=(s,a)=>{all=ReadEvents31(row.Host,10000);Show();load.IsEnabled=false;};top.Children.Add(load);var export=new Button{Content="Сохранить всю историю…"};export.Click+=(s,a)=>{var dialog=new Microsoft.Win32.SaveFileDialog{Filter="Текст|*.txt",FileName="client-events.txt"};if(dialog.ShowDialog(window)!=true)return;using var writer=new StreamWriter(dialog.FileName,false,new UTF8Encoding(true));var folder=EventFolder31(row.Host);if(Directory.Exists(folder))foreach(var file in Directory.GetFiles(folder,"*.jsonl").OrderBy(f=>f))foreach(var line in File.ReadLines(file)){try{var item=JsonSerializer.Deserialize<ClientEvent31>(line);if(item!=null)writer.WriteLine(item.Display+(item.Details.Length>0?"\n"+item.Details:""));}catch{}}};top.Children.Add(export);window.Content=panel;window.ShowDialog();}
